import cors from 'cors';
import express from 'express';
import rateLimit from 'express-rate-limit';
import helmet from 'helmet';
import { createProxyMiddleware } from 'http-proxy-middleware';
import path from 'path';
import pino from 'pino';
import pinoHttp from 'pino-http';
import { createServer as createViteServer } from 'vite';

const app = express();
const logger = pino();
app.use(pinoHttp({ logger, autoLogging: false })); // autoLogging: false to reduce noise, or true if we want all requests
app.use(helmet({
  contentSecurityPolicy: false // Disabled for Vite dev server compat; re-enable with strict config in production if needed
}));
app.use(cors({
  origin: process.env.CORS_ALLOWED_ORIGINS ? process.env.CORS_ALLOWED_ORIGINS.split(',') : ['http://localhost:5173', 'http://localhost:3000'],
  credentials: true
}));
app.use(express.json({ limit: '100kb' })); // Secure payload size

const logsLimiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 30,
  message: { success: false, message: 'Too many log requests from this IP' }
});

const PORT = Number(process.env.PORT) || 3000;
const API_GATEWAY_URL = process.env.API_GATEWAY_URL || 'http://localhost:8080';
const OLA_MAPS_API_KEY = process.env.OLA_MAPS_API_KEY || process.env.VITE_OLA_MAPS_API_KEY || '';

// Proxy all /olamaps/** requests to api.olamaps.io and attach the API key
app.use(
  '/olamaps',
  createProxyMiddleware({
    target: 'https://api.olamaps.io',
    changeOrigin: true,
    pathRewrite: { '^/olamaps': '' },
    on: {
      proxyReq: (proxyReq) => {
        const separator = proxyReq.path.includes('?') ? '&' : '?';
        proxyReq.path = `${proxyReq.path}${separator}api_key=${OLA_MAPS_API_KEY}`;
      },
      error: (err, req, res: any) => {
        logger.error({ err }, `[proxy] Error forwarding Ola Maps request: ${err.message}`);
        if (res && res.writeHead) {
          res.writeHead(502, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ success: false, message: 'Ola Maps unreachable: ' + err.message }));
        }
      },
    },
  })
);

// Ingest frontend logs
app.post('/api/logs', logsLimiter, (req, res) => {
  if (!req.headers.authorization) {
    return res.status(401).send({ success: false, message: 'Unauthorized' });
  }
  const { logs } = req.body;
  if (Array.isArray(logs)) {
    logs.forEach(log => {
      // Whitelist fields to prevent prototype pollution or large junk data
      const safeData = {
        message: String(log.message).substring(0, 500),
        stack: log.stack ? String(log.stack).substring(0, 2000) : undefined,
        context: log.context,
      };

      if (log.level === 'WARN') {
        logger.warn({ frontend: true, ...safeData }, `[Frontend] ${safeData.message}`);
      } else if (log.level === 'ERROR') {
        logger.error({ frontend: true, ...safeData }, `[Frontend] ${safeData.message}`);
      }
    });
  }
  res.status(200).send({ success: true });
});

// Proxy all /api/** requests to the API Gateway
app.use(
  '/api',
  createProxyMiddleware({
    target: API_GATEWAY_URL,
    changeOrigin: true,
      on: {
        proxyReq: (proxyReq, req: express.Request) => {
          // Forward original host for CORS
          if (req.headers.authorization) {
            proxyReq.setHeader('Authorization', req.headers.authorization);
          }
        },
        error: (err, req: express.Request, res: any) => {
          logger.error({ err }, `[proxy] Error forwarding ${req.method} ${req.url}: ${err.message}`);
          if (res && res.writeHead) {
            res.writeHead(502, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({ success: false, message: 'API Gateway unreachable: ' + err.message }));
          }
        },
      },
  })
);

async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  // Global Error Handler
  app.use((err: any, req: express.Request, res: express.Response, next: express.NextFunction) => {
    logger.error(err, 'Unhandled Express Exception');
    if (res.headersSent) {
      return next(err);
    }
    res.status(500).json({
      success: false,
      message: 'Internal Server Error' // Hides stack trace from client
    });
  });

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Proxying /api/* → ${API_GATEWAY_URL}`);
  });
}

startServer();

import { z } from 'zod';

export const adminActionSchema = z.object({
  action: z.string(),
  targetId: z.string().optional(),
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  payload: z.any().optional(),
}).passthrough();

export type AdminAction = z.infer<typeof adminActionSchema>;

export const adminMetricSchema = z.object({
  metricName: z.string(),
  value: z.number(),
  timestamp: z.string().optional(),
}).passthrough();

export type AdminMetric = z.infer<typeof adminMetricSchema>;

import { makeApi } from '@zodios/core';
export const adminApiDef = makeApi([
  {
    method: 'get',
    path: '/api/v1/admin/users',
    alias: 'getUsers',
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    response: z.any()
  },
  {
    method: 'get',
    path: '/api/v1/admin/dashboard',
    alias: 'getDashboard',
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    response: z.any()
  }
]);

import { CallEndReason, CallState, useWebRTC } from "@features/communication/models/useWebRTC";
import React, { createContext, ReactNode, useContext } from 'react';

interface CallContextType {
  callState: CallState;
  callEndReason: CallEndReason;
  isCaller: boolean;
  callerId: string | null;
  remoteUserId: string | null;
  remoteStream: MediaStream | null;
  startCall: (targetUserId: string, sessionId: string) => Promise<void>;
  acceptCall: () => Promise<void>;
  declineCall: () => void;
  endCall: () => void;
  toggleMute: () => boolean;
}

const CallContext = createContext<CallContextType | undefined>(undefined);

export const CallProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const rtcState = useWebRTC();

  return (
    <CallContext.Provider value={rtcState}>
      {children}
    </CallContext.Provider>
  );
};

export const useCallContext = () => {
  const context = useContext(CallContext);
  if (!context) {
    throw new Error('useCallContext must be used within a CallProvider');
  }
  return context;
};

import React, { createContext, useContext, useEffect, useState } from 'react';

interface ConfigContextType {
  olaMapsApiKey: string | null;
  isLoading: boolean;
  error: string | null;
}

const ConfigContext = createContext<ConfigContextType>({
  olaMapsApiKey: null,
  isLoading: true,
  error: null,
});

export const useConfig = () => useContext(ConfigContext);

export const ConfigProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [olaMapsApiKey, setOlaMapsApiKey] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const res = await window.fetch(import.meta.env.VITE_API_BASE_URL + '/api/config/ui-config', { headers: { 'X-Calling-Service': 'CustomerApplication' } });
        if (!res.ok) throw new Error('API Error');
        const response = await res.json();
        if (response && (response).mapsApiKey) {
          setOlaMapsApiKey((response).mapsApiKey);
        } else {
          setError('Failed to load Maps API Key from server');
        }
      } catch (err: unknown) {
        console.error('Error fetching config:', err);
        setError('Failed to fetch runtime configuration');
      } finally {
        setIsLoading(false);
      }
    };

    fetchConfig();
  }, []);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-slate-900 text-slate-200">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-amber-500 border-t-transparent rounded-full animate-spin"></div>
          <p>Initializing Application Configuration...</p>
        </div>
      </div>
    );
  }

  return (
    <ConfigContext.Provider value={{ olaMapsApiKey, isLoading, error }}>
      {children}
    </ConfigContext.Provider>
  );
};

import React, { createContext, useContext, useState } from 'react';

type Theme = 'light' | 'dark';

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light');

  // We don't apply the 'dark' class here because it's applied in App.tsx
  // based on this context. Or better, we can move the application of the class here.
  // Actually, we can just leave the class application in App.tsx using this context.

  const toggleTheme = () => {
    setTheme(prev => prev === 'dark' ? 'light' : 'dark');
  };

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

export function useTheme() {
  const context = useContext(ThemeContext);
  if (context === undefined) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
}

import { AnimatePresence, motion } from 'framer-motion';
import React, { createContext, ReactNode, useCallback, useContext, useState } from 'react';
import { createPortal } from 'react-dom';

type ToastType = 'success' | 'error' | 'info';

interface Toast {
  id: string;
  message: string;
  type: ToastType;
}

interface ToastContextType {
  showSuccess: (message: string) => void;
  showError: (message: string) => void;
  showInfo: (message: string) => void;
}

const ToastContext = createContext<ToastContextType | undefined>(undefined);

export const useToast = () => {
  const context = useContext(ToastContext);
  if (!context) {
    throw new Error('useToast must be used within a ToastProvider');
  }
  return context;
};

export const ToastProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback((message: string, type: ToastType) => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts((prev) => [...prev, { id, message, type }]);

    setTimeout(() => {
      setToasts((prev) => prev.filter((toast) => toast.id !== id));
    }, 3000);
  }, []);

  const showSuccess = useCallback((message: string) => addToast(message, 'success'), [addToast]);
  const showError = useCallback((message: string) => addToast(message, 'error'), [addToast]);
  const showInfo = useCallback((message: string) => addToast(message, 'info'), [addToast]);

  return (
    <ToastContext.Provider value={{ showSuccess, showError, showInfo }}>
      {children}
      {createPortal(
        <div style={{
          position: 'fixed',
          top: 20,
          left: '50%',
          transform: 'translateX(-50%)',
          zIndex: 9999,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '10px',
          pointerEvents: 'none'
        }}>
          <AnimatePresence>
            {toasts.map((toast) => (
              <motion.div
                key={toast.id}
                initial={{ opacity: 0, y: -20, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: -20, scale: 0.95, transition: { duration: 0.2 } }}
                style={{
                  background: 'rgba(25, 25, 25, 0.95)',
                  color: 'white',
                  padding: '12px 24px',
                  borderRadius: '12px',
                  boxShadow: '0 8px 32px rgba(0,0,0,0.2)',
                  backdropFilter: 'blur(10px)',
                  border: '1px solid rgba(255,255,255,0.1)',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '12px',
                  fontSize: '14px',
                  fontWeight: 500,
                  pointerEvents: 'auto'
                }}
              >
                {toast.type === 'success' && (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#4ade80" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
                    <polyline points="22 4 12 14.01 9 11.01"></polyline>
                  </svg>
                )}
                {toast.type === 'error' && (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#f87171" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="12" r="10"></circle>
                    <line x1="12" y1="8" x2="12" y2="12"></line>
                    <line x1="12" y1="16" x2="12.01" y2="16"></line>
                  </svg>
                )}
                {toast.type === 'info' && (
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <circle cx="12" cy="12" r="10"></circle>
                    <line x1="12" y1="16" x2="12" y2="12"></line>
                    <line x1="12" y1="8" x2="12.01" y2="8"></line>
                  </svg>
                )}
                <span>{toast.message}</span>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>,
        document.body
      )}
    </ToastContext.Provider>
  );
};

