import { getToken } from "@/lib/tokenStore";
import { customerApi, mapsApi } from "@/lib/zodiosClients";
import { MapPin, Search, X } from 'lucide-react';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { motion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';
import { z } from 'zod';
import { asUntyped, fromContract } from '../../../lib/untypedResponse';

const addressSchema = z.object({
  label: z.string().min(1, 'Label is required').max(50, 'Label cannot exceed 50 characters'),
  addressLine1: z.string().min(1, 'Address Line 1 is required').max(255, 'Address cannot exceed 255 characters'),
  city: z.string().min(1, 'City is required').max(100, 'City cannot exceed 100 characters'),
  state: z.string().min(1, 'State is required').max(100, 'State cannot exceed 100 characters'),
  zipCode: z.string().min(1, 'ZIP Code is required').max(20, 'ZIP Code cannot exceed 20 characters'),
  latitude: z.number().min(-90).max(90),
  longitude: z.number().min(-180).max(180)
});

window.maplibregl = maplibregl;

interface SearchSuggestion {
  description: string;
  geometry?: {
    location?: {
      lat: number;
      lng: number;
    }
  }
}

interface SavedAddress {
  id: string;
  label: string;
  addressLine1: string;
  addressLine2?: string;
  city: string;
  latitude: number | string;
  longitude: number | string;
}

interface CustomerAddressPageProps {
  setView: (view: string) => void;
  addressSearchQuery: string;
  setAddressSearchQuery: (val: string) => void;
  address: string;
  setAddress: (val: string) => void;
  onAddApiLog?: (log: unknown) => void;
  savedAddresses?: SavedAddress[];
  setSavedAddresses?: (updater: (prev: SavedAddress[]) => SavedAddress[]) => void;
  userId?: string;
}

export default function CustomerAddressPage({
  setView,
  addressSearchQuery,
  setAddressSearchQuery,
  address,
  setAddress,
  onAddApiLog = () => {},

  setSavedAddresses,
  userId
}: CustomerAddressPageProps) {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const [mapInstance, setMapInstance] = useState<maplibregl.Map | null>(null);
  const [suggestions, setSuggestions] = useState<SearchSuggestion[]>([]);
  const [, setIsSearching] = useState(false);

  const [label, setLabel] = useState('');
  const [city, setCity] = useState('');
  const [state, setState] = useState('');
  const [zipCode, setZipCode] = useState('');
  const [error, setError] = useState('');


  useEffect(() => {
    let active = true;
    let map: unknown = null;

    const initMap = async () => {
      try {
        if (onAddApiLog) {
           onAddApiLog({ id: 'fetch_maps_key', label: 'GET /api/config/maps-key', method: 'GET' });
        }
        if (!active || !mapContainerRef.current) return;

        map = new maplibregl.Map({
             container: mapContainerRef.current!,
             style: '/olamaps/styleEditor/v1/styleEdit/styles/53575843-c000-4b22-ac12-5818a67991bd/LowCost',
             minZoom: 10,
             maxZoom: 17,
             interactive: false,
             transformRequest: (url, _resourceType) => {
                 if (url.includes('api.olamaps.io')) {
                     return {
                         url: url.replace('https://api.olamaps.io', '/olamaps')
                     };
                 }
                 return { url };
             }
        });

        // @ts-expect-error auto-migration type suppression
        setMapInstance(map);

        // @ts-expect-error auto-migration type suppression
        map.on('moveend', async () => {
             try {
                // @ts-expect-error auto-migration type suppression
                const center = map.getCenter();
                if (onAddApiLog) {
                   onAddApiLog({ id: 'reverse_geocode', label: `GET /api/places/reverse-geocode?lat=${center.lat.toFixed(4)}&lng=${center.lng.toFixed(4)}`, method: 'GET' });
                }
                const res = await mapsApi.integration.get('/api/places/reverse-geocode', { queries: { lat: center.lat, lng: center.lng } });
                if (active && res.address) {
                   // @ts-expect-error auto-migration type suppression
                   setAddress(res.address);
                   const parts = (asUntyped<{ address?: string }>(res).address ?? '').split(',').map((p: string) => p.trim());
                   let zip = '';
                   let state = '';
                   let city = '';
                   let currentIndex = parts.length - 1;
                   if (currentIndex >= 0 && (parts[currentIndex].toLowerCase() === 'india' || parts[currentIndex].toLowerCase() === 'in')) {
                       currentIndex--;
                   }
                   if (currentIndex >= 0) {
                       const zipMatch = parts[currentIndex].match(/(.*?)\s+([\d\s-]{5,10})$/);
                       if (zipMatch) {
                           state = zipMatch[1].trim();
                           zip = zipMatch[2].trim();
                           currentIndex--;
                       } else if (/^[\d\s-]{5,10}$/.test(parts[currentIndex])) {
                           zip = parts[currentIndex];
                           currentIndex--;
                       }
                   }
                   if (currentIndex >= 0 && !state) {
                       state = parts[currentIndex];
                       currentIndex--;
                   }
                   if (currentIndex >= 0) {
                       city = parts[currentIndex];
                   }
                   if (zip) setZipCode(zip);
                   if (state) setState(state);
                   if (city) setCity(city);
                }
              } catch (e: unknown) {
                console.error(e);
              }
           });

           // Request geolocation
           if (navigator.geolocation) {
             navigator.geolocation.getCurrentPosition(
               (position) => {
                 const { latitude, longitude } = position.coords;
                 if (map && active) {
                   // @ts-expect-error auto-migration type suppression
                   map.flyTo({ center: [longitude, latitude], zoom: 16 });
                 }
               },
               (error) => {
                 console.error("Geolocation error:", error);
               },
               { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
             );
           }
      } catch (e: unknown) {
         console.error('Map init failed', e);
      }
    };

    initMap();

    return () => {
      active = false;
      if (map) {
         // @ts-expect-error auto-migration type suppression
         map.remove();
      }
    };
  }, []);

  useEffect(() => {
    if (!addressSearchQuery || addressSearchQuery.length < 3) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setSuggestions([]);
      return;
    }
    const timer = setTimeout(async () => {
       try {
         setIsSearching(true);
         if (onAddApiLog) {
            onAddApiLog({ id: 'autocomplete', label: `GET /api/places/autocomplete?input=${encodeURIComponent(addressSearchQuery)}`, method: 'GET' });
         }
         const res = await mapsApi.integration.get('/api/places/autocomplete', { queries: { input: addressSearchQuery } });
         setSuggestions(fromContract(res ?? []) as SearchSuggestion[]);
       } catch (e: unknown) {
         console.error(e);
       } finally {
         setIsSearching(false);
       }
    }, 500);
    return () => clearTimeout(timer);
  }, [addressSearchQuery]);

  const handleSuggestionClick = async (suggestion: SearchSuggestion) => {
      setAddressSearchQuery(suggestion.description);
      setSuggestions([]);
      const token = getToken();
      let loc = null;
      if (suggestion.geometry && suggestion.geometry.location) {
          loc = suggestion.geometry.location;
      } else {
          try {
              if (onAddApiLog) onAddApiLog({ id: 'geocode', label: `GET /api/places/geocode?address=${encodeURIComponent(suggestion.description)}`, method: 'GET' });
              const rawRes = await window.fetch(`/api/places/geocode?address=${encodeURIComponent(suggestion.description)}`, { headers: { Authorization: `Bearer ${token}`, 'X-Calling-Service': 'CustomerApplication' } });
              if (!rawRes.ok) throw new Error('API Error');
              const res = await rawRes.json();
              if (res && res.lat && res.lng) {
                  loc = res;
              }
          } catch (e: unknown) {
              console.error(e);
          }
      }

      if (loc && mapInstance) {
         mapInstance.flyTo({ center: [loc.lng, loc.lat], zoom: 16 });
         setAddress(suggestion.description);
         const parts = suggestion.description.split(',').map((p: string) => p.trim());
         let zip = '';
         let state = '';
         let city = '';
         let currentIndex = parts.length - 1;
         if (currentIndex >= 0 && (parts[currentIndex].toLowerCase() === 'india' || parts[currentIndex].toLowerCase() === 'in')) {
             currentIndex--;
         }
         if (currentIndex >= 0) {
             const zipMatch = parts[currentIndex].match(/(.*?)\s+([\d\s-]{5,10})$/);
             if (zipMatch) {
                 state = zipMatch[1].trim();
                 zip = zipMatch[2].trim();
                 currentIndex--;
             } else if (/^[\d\s-]{5,10}$/.test(parts[currentIndex])) {
                 zip = parts[currentIndex];
                 currentIndex--;
             }
         }
         if (currentIndex >= 0 && !state) {
             state = parts[currentIndex];
             currentIndex--;
         }
         if (currentIndex >= 0) {
             city = parts[currentIndex];
         }
         if (zip) setZipCode(zip);
         if (state) setState(state);
         if (city) setCity(city);
      }
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="flex-1 overflow-y-auto w-full p-5 flex flex-col space-y-4 bg-transparent"
    >
      <div className="flex items-center gap-3 shrink-0 mb-4">
        <button
          onClick={() => setView('settings')}
          className="p-2 rounded-xl bg-white/20 dark:bg-slate-900/20 backdrop-blur-md border border-rose-500/20 text-slate-500 dark:text-slate-300 hover:text-slate-900 hover:bg-white dark:hover:text-white cursor-pointer transition-all"
        >
          <X className="w-5 h-5" />
        </button>
        <div>
          <h4 className="font-bold text-xl text-slate-900 dark:text-[#f0ede6]">Delivery Location</h4>
          <p className="text-xs text-slate-500 dark:text-slate-300">Set your precise location for faster delivery</p>
        </div>
      </div>
      {error && (
        <div className="bg-rose-100 border border-rose-400 text-rose-700 px-4 py-3 rounded relative mb-2 text-sm" role="alert">
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      <div className="flex-1 overflow-y-auto pr-1">
        <div className="space-y-6">
          {/* Search Bar */}
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400 dark:text-slate-500" />
            <input
              type="text"
              placeholder="Search for area, street name..."
              value={addressSearchQuery}
              onChange={e => setAddressSearchQuery(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl py-4 pl-12 pr-4 text-base font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50"
            />
            {suggestions.length > 0 && (
              <div className="absolute top-full left-0 right-0 mt-2 bg-white dark:bg-slate-800 rounded-xl shadow-xl border border-slate-100 dark:border-slate-700 max-h-64 overflow-y-auto z-10">
                {suggestions.map((s, idx) => (
                  <div 
                    key={idx} 
                    onClick={() => handleSuggestionClick(s)}
                    className="px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-700 cursor-pointer border-b last:border-b-0 border-slate-100 dark:border-slate-700"
                  >
                    <p className="text-sm text-slate-800 dark:text-[#f0ede6] truncate">{s.description}</p>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Map Container */}
          <div className="relative w-full h-[300px] rounded-3xl overflow-hidden bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-800 shrink-0 shadow-inner">
            <div ref={mapContainerRef} className="absolute inset-0 w-full h-full" />
            {/* Fixed Center Pin */}
            <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
              <div className="w-16 h-16 bg-rose-500/20 rounded-full flex items-center justify-center animate-pulse">
                <div className="w-10 h-10 bg-rose-500 text-white rounded-full flex items-center justify-center shadow-2xl mb-5">
                  <MapPin className="w-5 h-5" />
                </div>
              </div>
            </div>
          </div>

          {/* Current Address Details */}
          <div className="space-y-4 bg-white/20 dark:bg-slate-900/20 backdrop-blur-md/50 p-5 sm:p-6 rounded-3xl border border-slate-100 dark:border-slate-800 shadow-sm">
            <div className="flex gap-4">
               <div className="flex-1 space-y-1.5">
                  <label className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider">Label</label>
                  <input
                    type="text"
                    value={label}
                    onChange={e => setLabel(e.target.value)}
                    placeholder="e.g. Home, Work"
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50"
                  />
               </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider">Address Line 1</label>
              <textarea
                value={address}
                onChange={(e) => { setAddress(e.target.value); setError(''); }}
                rows={2}
                className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50 resize-none"
                required
                minLength={5}
                maxLength={255}
              />
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
               <div className="space-y-1.5">
                  <label className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider">City</label>
                  <input
                    type="text"
                    value={city}
                    onChange={e => { setCity(e.target.value); setError(''); }}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50"
                    required
                    minLength={2}
                    maxLength={100}
                  />
               </div>
               <div className="space-y-1.5">
                  <label className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider">State</label>
                  <input
                    type="text"
                    value={state}
                    onChange={e => { setState(e.target.value); setError(''); }}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50"
                    required
                    minLength={2}
                    maxLength={100}
                  />
               </div>
               <div className="space-y-1.5">
                  <label className="text-xs font-bold font-mono text-slate-500 dark:text-slate-400 uppercase tracking-wider">Zip</label>
                  <input
                    type="text"
                    value={zipCode}
                    onChange={e => { setZipCode(e.target.value); setError(''); }}
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-3 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-rose-500/50"
                    required
                    pattern="^\d{5,10}$"
                  />
               </div>
            </div>
            </div>

             <div className="pt-4">
               <button
                 onClick={async () => {
                   const payload = {
                     label: label || 'New Address',
                     addressLine1: address,
                     city: city,
                     state: state,
                     zipCode: zipCode,
                     latitude: mapInstance ? mapInstance.getCenter().lat : 12.9716,
                     longitude: mapInstance ? mapInstance.getCenter().lng : 77.5946
                   };

                   const validation = addressSchema.safeParse(payload);
                   if (!validation.success) {
                     setError(validation.error.issues[0].message);
                     return;
                   }

                   if (setSavedAddresses && userId) {
                     try {
                       const res = await customerApi.customerAddress.post('/api/v1/customers/:customerId/addresses', payload, { params: { customerId: userId } });
                       const data = res?.data || res;
                       if (data && data.id) {
                         setSavedAddresses((prev) => [...prev, data as SavedAddress]);
                       }
                     } catch (e: unknown) {
                        console.error("Failed to save address", e);
                     }
                   }
                   setView('settings');
                 }}
                 className="w-full py-3.5 bg-rose-500 text-white rounded-xl font-bold shadow-lg shadow-rose-500/20 active:scale-95 transition-all"
               >
                 Confirm Location
               </button>
             </div>

        </div>
      </div>
    </motion.div>
  );
}

import { useConfig } from "@/contexts/ConfigContext";
import { Modal } from '@shared/ui';
import { Check, MapPin, Navigation } from 'lucide-react';
import React from 'react';

interface CustomerAddressSelectorModalProps {
  isOpen: boolean;
  onClose: () => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  savedAddresses: any[];
  address: string;
  setAddress: (address: string) => void;
  setDeliveryLat: (lat: number) => void;
  setDeliveryLng: (lng: number) => void;
  setDeliveryAddressId: (id: string) => void;
  currentAddressId?: string;
  setShowLocationPrompt: (show: boolean) => void;
  onAddNewAddress: () => void;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  carts?: any;
  clearCart?: (restaurantId: string) => void;
}

const CustomerAddressSelectorModal: React.FC<CustomerAddressSelectorModalProps> = ({
  isOpen,
  onClose,
  savedAddresses,
  address,
  setAddress,
  setDeliveryLat,
  setDeliveryLng,
  setDeliveryAddressId,
  currentAddressId,
  setShowLocationPrompt,
  onAddNewAddress,
  carts,
  clearCart
}) => {
  useConfig();
  const handleAddressSelect = (addr: string, lat?: number, lng?: number, id?: string) => {
    // If id is provided (saved address), check if it's different from current
    // If no id (GPS), check if the address string is different
    const isDifferent = id ? id !== currentAddressId : addr !== address;

    if (isDifferent) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const hasItems = Object.values(carts || {}).some((cart: any) => cart.items && cart.items.length > 0);
      if (hasItems) {
        if (!window.confirm("Changing your address will clear your active cart. Do you want to continue?")) {
          return;
        }
        Object.keys(carts || {}).forEach(restaurantId => {
          if (carts[restaurantId]?.items?.length > 0 && clearCart) {
            clearCart(restaurantId);
          }
        });
      }
    }

    setAddress(addr);
    if (lat !== undefined && lng !== undefined) {
      setDeliveryLat(lat);
      setDeliveryLng(lng);
    }
    setDeliveryAddressId(id || '');
    onClose();
  };
  return (
    <Modal isOpen={isOpen} onClose={onClose} title="Select Delivery Location" size="md">
      <div className="p-4 space-y-3 pb-8">
        <button
          onClick={() => {
            if (navigator.geolocation) {
              navigator.geolocation.getCurrentPosition(async (pos) => {
                try {
                  const res = await window.fetch(`/olamaps/places/v1/reverse-geocode?latlng=${pos.coords.latitude},${pos.coords.longitude}`);
                  const data = await res.json();
                  if (data.results && data.results.length > 0) {
                    handleAddressSelect(`Current Location: ${data.results[0].formatted_address}`, pos.coords.latitude, pos.coords.longitude, '');
                  } else {
                    handleAddressSelect('Current Location', pos.coords.latitude, pos.coords.longitude, '');
                  }
                } catch (e: unknown) {
                  handleAddressSelect('Current Location', pos.coords.latitude, pos.coords.longitude, '');
                }
              }, (err) => {
                if (err.code === err.PERMISSION_DENIED) {
                  onClose();
                  setShowLocationPrompt(true);
                }
              });
            }
          }}
          className={`w-full flex items-center gap-3 p-3 rounded-xl border transition-colors text-left cursor-pointer ${!currentAddressId
              ? 'border-indigo-500 bg-indigo-50/50 dark:bg-indigo-500/20'
              : 'border-indigo-100 dark:border-indigo-500/20 hover:bg-indigo-50 dark:hover:bg-indigo-500/20'
            }`}
        >
          <Navigation className={`w-5 h-5 shrink-0 ${!currentAddressId ? 'text-indigo-600 dark:text-indigo-400' : 'text-indigo-500'}`} />
          <div className="flex-1">
            <p className={`font-bold ${!currentAddressId ? 'text-indigo-700 dark:text-indigo-300' : 'text-indigo-600 dark:text-indigo-400'}`}>Use Current Location</p>
            <p className="text-xs text-indigo-500/80 dark:text-indigo-400/80">Using GPS</p>
          </div>
          {!currentAddressId && (
            <div className="w-5 h-5 rounded-full bg-indigo-500 flex items-center justify-center shrink-0">
              <Check className="w-3 h-3 text-white" />
            </div>
          )}
        </button>

        <button
          onClick={() => {
            onClose();
            onAddNewAddress();
          }}
          className="w-full flex items-center gap-3 p-3 rounded-xl border border-rose-100 dark:border-rose-500/20 bg-rose-50/50 dark:bg-rose-500/10 hover:bg-rose-50 dark:hover:bg-rose-500/20 transition-colors text-left cursor-pointer"
        >
          <MapPin className="w-5 h-5 text-rose-500 shrink-0" />
          <div>
            <p className="font-bold text-rose-600 dark:text-rose-400">Add New Address</p>
            <p className="text-xs text-rose-500/80 dark:text-rose-400/80">Search or pick from map</p>
          </div>
        </button>

        <div className="pt-2">
          <p className="text-xs font-bold text-slate-400 dark:text-slate-500 mb-3 px-1 uppercase tracking-wider">Saved Addresses</p>
          {savedAddresses.length > 0 ? (
            <div className="space-y-2">
              {savedAddresses.map(addr => (
                <button
                  key={addr.id}
                  onClick={() => {
                    handleAddressSelect(
                      `${addr.label}: ${addr.addressLine1}${addr.addressLine2 ? ', ' + addr.addressLine2 : ''}, ${addr.city}`,
                      addr.latitude,
                      addr.longitude,
                      addr.id
                    );
                  }}
                  className={`w-full flex items-start gap-3 p-3 rounded-xl border transition-colors text-left group cursor-pointer ${addr.id === currentAddressId
                      ? 'border-rose-500 bg-rose-50 dark:bg-rose-500/10'
                      : 'border-slate-100 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700'
                    }`}
                >
                  <MapPin className={`w-5 h-5 mt-0.5 shrink-0 transition-colors ${addr.id === currentAddressId
                      ? 'text-rose-500'
                      : 'text-slate-400 group-hover:text-rose-500'
                    }`} />
                  <div className="flex-1 min-w-0">
                    <p className={`font-bold text-sm ${addr.id === currentAddressId ? 'text-rose-700 dark:text-rose-400' : 'text-slate-900 dark:text-white'}`}>{addr.label}</p>
                    <p className={`text-xs leading-relaxed mt-0.5 line-clamp-2 ${addr.id === currentAddressId ? 'text-rose-600/80 dark:text-rose-400/80' : 'text-slate-500 dark:text-slate-400'}`}>
                      {addr.addressLine1}{addr.addressLine2 ? ', ' + addr.addressLine2 : ''}, {addr.city}
                    </p>
                  </div>
                  {addr.id === currentAddressId && (
                    <div className="w-5 h-5 rounded-full bg-rose-500 flex items-center justify-center shrink-0 mt-1">
                      <Check className="w-3 h-3 text-white" />
                    </div>
                  )}
                </button>
              ))}
            </div>
          ) : (
            <p className="text-sm text-slate-500 dark:text-slate-400 px-1">No saved addresses found.</p>
          )}
        </div>
      </div>
    </Modal>
  );
};

export default CustomerAddressSelectorModal;

