import { usePolling } from "@/hooks/usePolling";
import { getToken } from "@/lib/tokenStore";
import { deliveryApi } from "@/lib/zodiosClients";
import { DeliveryStatus, Order, OrderStatus } from "@/types";
import { isActiveOrder } from '@features/customer-orders/model/orderStatus';
import { fetchEventSource } from '@microsoft/fetch-event-source';
import { useEffect, useRef, useState } from 'react';

export interface UseDeliveryOrdersProps {
  riderId: string;
  riderName: string;
  isOnline: boolean;
  setIsOnline: (online: boolean) => void;
  showToast: (msg: string) => void;
  externalOrders?: Order[];
  externalUpdateStatus?: (orderId: string, status: OrderStatus, deliveryStatus?: DeliveryStatus, riderInfo?: unknown) => void;
  setShowPermissionsPrompt: (show: boolean) => void;
  onAddApiLog?: (log: unknown) => void;
}

export function useDeliveryOrders({
  riderId,

  isOnline,
  setIsOnline,
  showToast,
  externalOrders,
  externalUpdateStatus,
  setShowPermissionsPrompt,
  onAddApiLog
}: UseDeliveryOrdersProps) {
  const [internalOrders, setInternalOrders] = useState<Order[]>([]);
  const activeOrders = externalOrders ?? internalOrders;

  const onUpdateOrderStatus = externalUpdateStatus ?? ((orderId: string, status: OrderStatus, deliveryStatus?: DeliveryStatus, _riderInfo?: unknown) => {
    setInternalOrders(prev => prev.map(o => o.id === orderId ? { ...o, status, ...(deliveryStatus ? { deliveryStatus } : {}) } : o));
  });

  const [wsConnected, setWsConnected] = useState(false);
  const todayDateString = new Date().toISOString().split('T')[0];
  const [historyDateFilter, setHistoryDateFilter] = useState(todayDateString);
  const [historyPage, setHistoryPage] = useState(1);
  const [showHistory, setShowHistory] = useState(false);

  const [activeJobId, setActiveJobId] = useState<string | null>(null);

  // Use a ref to ensure the websocket interval always captures the latest active order ID
  const activeJobIdRef = useRef<string | null>(null);

  useEffect(() => {
    activeJobIdRef.current = activeJobId;
  }, [activeJobId]);

  const [pingJob, setPingJob] = useState<Order | null>(null);
  const [pingTimer, setPingTimer] = useState(30);
  const [rejectedIds, setRejectedIds] = useState<Set<string>>(new Set());
  const historyRef = useRef<Order[]>([]);
  const lastActiveCountRef = useRef(0);

  // Polling Orders
  usePolling({
    fetchFn: async () => {
    if (!isOnline || !riderId) return;

    let fetchedActiveJobs: Order[] = [];
    let fetchedAvailableJobs: Order[] = [];
    const getArrayFromRes = (res: unknown) => (res as {content?: unknown[]}).content || (res as {data?:{data?:unknown[]}}).data?.data || (res as {data?:unknown[]}).data || (Array.isArray(res) ? res : []);

    try {
      const activeRes = await deliveryApi.deliveryOrder.get(`/api/v1/delivery/orders/active`, {});
      if (activeRes) {
         const activeData = getArrayFromRes(activeRes);
         fetchedActiveJobs = activeData.map((o: unknown) => ({ ...(o as Order), status: ((o as Order).status as string)?.toUpperCase() as OrderStatus || '' as OrderStatus }));
      }

      if (fetchedActiveJobs.length === 0) {
         const availableRes = await deliveryApi.deliveryOrder.get(`/api/v1/delivery/orders/available`, {});
         if (availableRes) {
            const availableData = getArrayFromRes(availableRes);
            fetchedAvailableJobs = availableData.map((o: unknown) => ({ ...(o as Order), status: ((o as Order).status as string)?.toUpperCase() as OrderStatus || '' as OrderStatus }));
            if (fetchedAvailableJobs.length > 0) {
              const newPingId = fetchedAvailableJobs[0].id;
              setRejectedIds(prev => {
                if (prev.has(newPingId)) {
                  const newSet = new Set(prev);
                  newSet.delete(newPingId);
                  return newSet;
                }
                return prev;
              });
            }
         }
      }

      const hasStaleActiveJobInHistory = historyRef.current.some(j => 
          j.deliveryStatus !== DeliveryStatus.DELIVERED && 
          j.deliveryStatus !== DeliveryStatus.FAILED && 
          j.status !== OrderStatus.CANCELLED && 
          j.status !== OrderStatus.CANCELLED_BY_RESTAURANT && 
          !fetchedActiveJobs.find(a => a.id === j.id)
      );

      if ((lastActiveCountRef.current > 0 && fetchedActiveJobs.length === 0) || hasStaleActiveJobInHistory) {
         const histRes = await deliveryApi.deliveryOrder.get('/api/v1/delivery/orders/history', { queries: { date: todayDateString } });
         if (histRes) {
            const histData = getArrayFromRes(histRes);
            historyRef.current = histData.map((o: unknown) => ({ ...(o as Order), status: ((o as Order).status as string)?.toUpperCase() as OrderStatus || '' as OrderStatus }));
         }
      }

      lastActiveCountRef.current = fetchedActiveJobs.length;

      setInternalOrders(() => {
        const mergedMap = new Map();
        historyRef.current.forEach(j => mergedMap.set(j.id, j));
        fetchedActiveJobs.forEach(j => mergedMap.set(j.id, j));
        fetchedAvailableJobs.forEach(j => mergedMap.set(j.id, j));
        return Array.from(mergedMap.values());
      });
    } catch (err: unknown) {
      console.error(err);
    }
  }, 
  intervalMs: 5000, 
  enabled: isOnline 
});

  // History Fetch
  useEffect(() => {
    if (!isOnline || !riderId) return;

    const dateToFetch = showHistory ? historyDateFilter : todayDateString;
    if (!dateToFetch) return;

    deliveryApi.deliveryOrder.get('/api/v1/delivery/orders/history', { queries: { date: dateToFetch } }).then(res => {
      if (res) {
        const getArrayFromRes = (res: unknown) => (res as {content?: unknown[]}).content || (res as {data?:{data?:unknown[]}}).data?.data || (res as {data?:unknown[]}).data || (Array.isArray(res) ? res : []);
        const histData = getArrayFromRes(res);
        historyRef.current = histData.map((o: unknown) => ({ ...(o as Order), status: ((o as Order).status as string)?.toUpperCase() as OrderStatus || '' as OrderStatus }));
        setInternalOrders(prev => {
          const active = prev.filter(o => isActiveOrder(o));
          const mergedMap = new Map();
          historyRef.current.forEach((j: Order) => mergedMap.set(j.id, j));
          active.forEach(j => mergedMap.set(j.id, j));
          return Array.from(mergedMap.values());
        });
      }
    }).catch(console.error);
  }, [showHistory, historyDateFilter, isOnline, riderId]);

  // Ping Job / Dispatch Logic
  useEffect(() => {
    if (isOnline && !activeJobId && !pingJob) {
      const jobs = activeOrders.filter(o => !o.riderId && !rejectedIds.has(o.id));
      if (jobs.length > 0) {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setPingJob(jobs[0]);
        if ((jobs[0]).remainingPingSeconds !== undefined) {
          setPingTimer((jobs[0]).remainingPingSeconds);
        } else if ((jobs[0]).expiresAt) {
          const remainingSecs = Math.max(0, Math.floor((new Date((jobs[0]).expiresAt).getTime() - Date.now()) / 1000));
          setPingTimer(remainingSecs);
        } else {
          setPingTimer(60);
        }
      }
    }
    if (!isOnline || activeJobId) {
      setPingJob(null);
    } else if (pingJob) {
      const stillActive = activeOrders.find(o => o.id === pingJob.id);
      if (!stillActive) {
        setPingJob(null);
      }
    }
  }, [activeOrders, isOnline, activeJobId, rejectedIds, pingJob]);

  useEffect(() => {
    if (!activeJobId) {
      const ongoingJob = activeOrders.find(o => (o.riderId === riderId || !!o.riderId) && o.deliveryStatus !== DeliveryStatus.DELIVERED && o.status !== OrderStatus.CANCELLED && o.status !== OrderStatus.CANCELLED_BY_RESTAURANT && o.deliveryStatus !== DeliveryStatus.FAILED);
      if (ongoingJob) {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setActiveJobId(ongoingJob.id);
      }
    } else {
      const currentJob = activeOrders.find(o => o.id === activeJobId);
      const currentJobStatus = currentJob?.status;
      const currentJobDeliveryStatus = currentJob?.deliveryStatus;
      if (!currentJob || currentJobStatus === OrderStatus.CANCELLED || currentJobStatus === OrderStatus.CANCELLED_BY_RESTAURANT || currentJobDeliveryStatus === DeliveryStatus.FAILED || currentJobDeliveryStatus === DeliveryStatus.DELIVERED) {
        if (currentJobDeliveryStatus === DeliveryStatus.FAILED || currentJobStatus === OrderStatus.CANCELLED || currentJobStatus === OrderStatus.CANCELLED_BY_RESTAURANT) {
           showToast("Your current order is no longer active (cancelled or failed).");
        }
        setActiveJobId(null);
      }
    }
  }, [activeOrders, riderId, activeJobId]);

  useEffect(() => {
    if (pingJob) {
      try {
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        if (AudioContext) {
          const ctx = new AudioContext();
          const osc = ctx.createOscillator();
          const gainNode = ctx.createGain();

          osc.type = 'sine';
          osc.frequency.setValueAtTime(880, ctx.currentTime);
          osc.frequency.exponentialRampToValueAtTime(1760, ctx.currentTime + 0.1);

          gainNode.gain.setValueAtTime(0, ctx.currentTime);
          gainNode.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 0.05);
          gainNode.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);

          osc.connect(gainNode);
          gainNode.connect(ctx.destination);

          osc.start(ctx.currentTime);
          osc.stop(ctx.currentTime + 0.5);
        }
      } catch {
        // best effort: WebAudio is unavailable in some browsers/contexts
      }

      const timer = setInterval(() => {
        setPingTimer(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            setRejectedIds(prev => new Set(prev).add(pingJob.id));
            setPingJob(null);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
      return () => clearInterval(timer);
    }
  }, [pingJob]);

  // WebSocket Location & Tracking
  useEffect(() => {
    if (!isOnline || !riderId) return;
    let ws: WebSocket;
    let interval: NodeJS.Timeout;
    let watchId: number;
    let currentLat = 12.9716;
    let currentLng = 77.5946;

    if (navigator.geolocation) {
      watchId = navigator.geolocation.watchPosition(
        (pos) => {
          currentLat = pos.coords.latitude;
          currentLng = pos.coords.longitude;
        },
        (err) => {
          console.error("Location error:", err);
          if (riderId) {
            (deliveryApi.deliveryExecutive.post(`/api/delivery/status`, { driverId: riderId, available: false }, {}))
              .catch(e => console.error(e));
          }
          setIsOnline(false);
          setShowPermissionsPrompt(true);
        },
        { enableHighAccuracy: true }
      );
    }
    let reconnectTimeout: NodeJS.Timeout;
    let attempt = 0;

    const connectWs = () => {
      const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
      const token = getToken();
      ws = new WebSocket(`${protocol}//${window.location.host}/api/delivery/tracking?token=${token}`);

      ws.onopen = () => {
        attempt = 0;
        setWsConnected(true);

        const sendLocation = () => {
          if (ws.readyState === WebSocket.OPEN) {
            const payload: { driverId: string, lat: number, lng: number, timestamp: string, orderId?: string } = { driverId: riderId, lat: currentLat, lng: currentLng, timestamp: new Date().toISOString() };
            if (activeJobIdRef.current) {
                payload.orderId = activeJobIdRef.current;
            }
            ws.send(JSON.stringify(payload));
          }
        };
        sendLocation();
        interval = setInterval(sendLocation, 5000);
      };

      ws.onmessage = async (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.type === "NEW_ORDER_DISPATCH" && data.orderId) {
            const pingRes = await deliveryApi.deliveryOrder.get(`/api/v1/delivery/orders/available`, {});
            const pingData = pingRes;
            if (pingData && pingData.length > 0) {
              const jobs = (pingData as unknown[]).map((o: unknown) => ({ ...(o as Order), status: ((o as Order).status as string)?.toUpperCase() as OrderStatus || '' as OrderStatus }));
              setRejectedIds(prev => {
                const newSet = new Set(prev);
                newSet.delete(jobs[0].id);
                return newSet;
              });
              setInternalOrders(prev => {
                const mergedMap = new Map();
                prev.forEach(j => mergedMap.set(j.id, j));
                jobs.forEach((j: Order) => mergedMap.set(j.id, j));
                return Array.from(mergedMap.values());
              });
              setPingJob(jobs[0]);
              if (jobs[0].remainingPingSeconds !== undefined) {
                setPingTimer(jobs[0].remainingPingSeconds);
              } else if (jobs[0].expiresAt) {
                const remainingSecs = Math.max(0, Math.floor((new Date(jobs[0].expiresAt).getTime() - Date.now()) / 1000));
                setPingTimer(remainingSecs);
              } else {
                setPingTimer(60);
              }
            }
          }
        } catch (e: unknown) {
          console.error("Failed to parse websocket message", e);
        }
      };

      ws.onclose = () => {
        setWsConnected(false);
        if (interval) clearInterval(interval);
        const delay = Math.min(1000 * Math.pow(2, attempt), 30000);
        attempt++;
        reconnectTimeout = setTimeout(() => { connectWs(); }, delay);
      };

      ws.onerror = (err) => {
        console.error("WebSocket error:", err);
        ws.close();
      };
    };

    connectWs();

    return () => {
      if (interval) clearInterval(interval);
      if (reconnectTimeout) clearTimeout(reconnectTimeout);
      if (ws) {
        ws.onclose = null;
        ws.close();
      }
      if (watchId !== undefined && navigator.geolocation) {
        navigator.geolocation.clearWatch(watchId);
      }
    };
  }, [isOnline, riderId]);

  // Current active job handling and SSE for status updates
  const currentJob = activeOrders.find(o => o.id === activeJobId && o.deliveryStatus !== DeliveryStatus.DELIVERED);

  useEffect(() => {
    if (currentJob && onAddApiLog) {
      onAddApiLog({ id: 'delivery_route', label: `GET /api/v1/logistics/route?sourceLat={riderLat}&sourceLng={riderLng}&destLat=${currentJob.deliveryLat}&destLng=${currentJob.deliveryLng}`, method: 'GET' });
    }
  }, [currentJob?.id, currentJob?.status]);

  useEffect(() => {
    if (!currentJob?.id || !riderId) return;
    const ctrl = new AbortController();
    let retryCount = 0;

    const connectSSE = async () => {
      const token = getToken();
      const url = `${import.meta.env?.VITE_API_BASE_URL || ''}/api/delivery/drivers/${riderId}/orders/${currentJob.id}/restaurant-status-stream`;

      try {
        await fetchEventSource(url, {
          method: 'GET',
          headers: token ? {
            'Authorization': `Bearer ${token}`,
            'Accept': 'text/event-stream'
          } : { 'Accept': 'text/event-stream' },
          signal: ctrl.signal,
          async onopen(res) {
            if (res.ok && res.status === 200) {
              retryCount = 0;
            } else if (res.status >= 400 && res.status < 500 && res.status !== 429) {
              throw new Error(`Fatal SSE error: ${res.status}`);
            }
          },
          onmessage(event) {
            retryCount = 0;
            if (event.event === 'status-update' || !event.event) {
              const newStatus = event.data as OrderStatus;
              onUpdateOrderStatus(currentJob.id, newStatus, currentJob.deliveryStatus);
              if (newStatus === OrderStatus.READY_FOR_PICKUP) {
                showToast(`Order ${currentJob.id.substring(0, 8)} is now ready for pickup!`);
              }
            }
          },
          onerror() {
            retryCount++;
            return Math.min(1000 * Math.pow(2, retryCount - 1), 16000);
          }
        });
      } catch {
        // best effort cleanup on unmount; nothing to recover
      }
    };

    connectSSE();
    return () => { ctrl.abort(); };
  }, [currentJob?.id, riderId]);

  // Derived Values
  const availableJobs = activeOrders.filter(o => (o.status === OrderStatus.READY_FOR_PICKUP || o.status === OrderStatus.PREPARING || o.status === OrderStatus.ACCEPTED) && !o.riderId);
  const allHistoryJobsMap = new Map();
  [...historyRef.current, ...activeOrders.filter(o => o.riderId === riderId && [DeliveryStatus.DELIVERED, DeliveryStatus.FAILED, DeliveryStatus.CANCELLED].includes(o.deliveryStatus as DeliveryStatus))]
    .forEach(job => allHistoryJobsMap.set(job.id, { ...job, payout: job.payout || 0 }));
  const allHistoryJobs = Array.from(allHistoryJobsMap.values());
  const todayHistoryJobs = allHistoryJobs.filter(job => job.createdAt?.startsWith(todayDateString));
  const todayEarnings = todayHistoryJobs.reduce((acc, job) => acc + (job.payout || 0), 0);
  const todayCompletedCount = todayHistoryJobs.length;

  const filteredHistoryJobs = allHistoryJobs.filter(job => {
    if (!historyDateFilter) return true;
    if (!job.createdAt) return false;
    return job.createdAt.startsWith(historyDateFilter);
  });
  const historyPageSize = 100;
  const paginatedHistoryJobs = filteredHistoryJobs.slice((historyPage - 1) * historyPageSize, historyPage * historyPageSize);
  const totalHistoryPages = Math.ceil(filteredHistoryJobs.length / historyPageSize);

  return {
    activeOrders,
    wsConnected,
    historyDateFilter,
    setHistoryDateFilter,
    historyPage,
    setHistoryPage,
    showHistory,
    setShowHistory,
    activeJobId,
    setActiveJobId,
    currentJob,
    pingJob,
    setPingJob,
    pingTimer,
    setPingTimer,
    rejectedIds,
    setRejectedIds,
    availableJobs,
    todayEarnings,
    todayCompletedCount,
    paginatedHistoryJobs,
    totalHistoryPages,
    historyRef,
    onUpdateOrderStatus
  };
}

import { logout } from "@/lib/authStore";
import { clearAllLocalData, decodeJwt, getToken, setToken, setUserProfile } from "@/lib/tokenStore";
import { otpSchema, phoneSchema as phoneNumberSchema } from "@/lib/zod-schemas";
import { identityApi } from "@/lib/zodiosClients";
import { RoleName, UserRole } from "@/types";
import { RoleSelector } from "@features/identity/components/RoleSelector";
import SessionManagementModal from "@features/identity/components/SessionManagementModal";
import { CompleteProfileModal } from "@shared/ui";
import LaBouffeLogo from '@shared/ui/LaBouffeLogo';
import { LaBouffeLogoMark } from '@shared/ui/LaBouffeLogoMark';
import { ArrowLeft, MessageSquare, Moon, Sun } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import React, { useEffect, useRef, useState } from 'react';
import { AuthForm } from './AuthForm';

const roleToServiceName = (role: UserRole): string => {
  switch (role) {
    case RoleName.CUSTOMER: return RoleName.CUSTOMER;
    case RoleName.RESTAURANT: return RoleName.RESTAURANT;
    case RoleName.DELIVERY: return RoleName.DELIVERY;
    case RoleName.ADMIN: return RoleName.ADMIN;
    default: return RoleName.CUSTOMER;
  }
};

interface LoginScreenProps {
  onLoginSuccess: (role: UserRole, phoneNumber: string, name: string) => void;
  onAddApiLog?: (log: unknown) => void;
}

import { useTheme } from "@/contexts/ThemeContext";

export default function LoginScreen({ onLoginSuccess, onAddApiLog }: LoginScreenProps) {
  const { theme, toggleTheme } = useTheme();
  const [selectedRole, setSelectedRole] = useState<UserRole | null>(null);
  const [phoneNumber, setPhone] = useState('');
  const [otpSent, setOtpSent] = useState(false);
  const [otpCode, setOtpCode] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showNotification, setShowNotification] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showSessionModal, setShowSessionModal] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [activeSessions, setActiveSessions] = useState<any[]>([]);
  const [showProfileModal, setShowProfileModal] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [pendingLoginData, setPendingLoginData] = useState<any>(null);

  const [scrollY, setScrollY] = useState(0);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollY(e.currentTarget.scrollTop);
  };

  const foodImages = [
    'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=800&q=80', // Burger
    'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=800&q=80', // Pizza
    'https://images.unsplash.com/photo-1579871494447-9811cf80d66c?auto=format&fit=crop&w=800&q=80', // Sushi
    'https://images.unsplash.com/photo-1565299624946-b28f40a0ae38?auto=format&fit=crop&w=800&q=80', // Pasta
    'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', // Salad
    'https://images.unsplash.com/photo-1551024601-bec78aea704b?auto=format&fit=crop&w=800&q=80'  // Dessert
  ];

  const foodNames = [
    'Smashed Cheeseburger',
    'Wood-Fired Neapolitan Pizza',
    'Premium Sushi & Sashimi Platter',
    'Handmade Italian Pasta',
    'Mediterranean Garden Salad',
    'Artisanal Glazed Dessert'
  ];

  const [currentBgIndex, setCurrentBgIndex] = useState(0);

  useEffect(() => {
    // Proactively clear backend session and local data if a user lands on login
    // This handles the edge case where session is lost locally but active on backend.
    const token = getToken();
    if (token) {
      logout().catch(console.error);
    } else {
      clearAllLocalData();
    }
  }, []);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentBgIndex((prev) => (prev + 1) % foodImages.length);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  // Auto dismiss or show SMS simulation
  useEffect(() => {
    if (otpSent && generatedOtp && (import.meta.env.DEV || import.meta.env.VITE_ENABLE_DEV_OTP === 'true')) {
      const timer = setTimeout(() => {
        setShowNotification(true);
      }, 1000);

      return () => clearTimeout(timer);
    }
  }, [otpSent, generatedOtp]);

  const handleSendOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const validation = phoneNumberSchema.safeParse(phoneNumber);
    if (!validation.success) {
      setError(validation.error.issues[0].message);
      return;
    }

    setLoading(true);

    if (onAddApiLog) {
      onAddApiLog({ id: 'auth_initiate', label: 'POST /api/v1/internal/auth/initiate', method: 'POST' });
    }

    try {
      const serviceName = roleToServiceName(selectedRole!);
      await identityApi.auth.post('/api/v1/internal/auth/initiate', undefined, { queries: { phoneNumber }, headers: { 'X-Calling-Service': serviceName } });

      // Try to fetch the OTP via admin endpoint (dev convenience or feature flag)
      if (import.meta.env.DEV || import.meta.env.VITE_ENABLE_DEV_OTP === 'true') {
        try {
          const adminResp = await identityApi.adminOtp.get('/api/v1/internal/auth/admin/otp', { queries: { phoneNumber, serviceName } });
          if (adminResp?.data) {
            setGeneratedOtp(adminResp.data);
          } else if (typeof adminResp === 'string') {
            setGeneratedOtp(adminResp);
          }
        } catch {
          console.warn("Could not fetch OTP from admin endpoint.");
        }
      }

      setOtpSent(true);
    } catch (err: unknown) {
      // @ts-expect-error auto-migration type suppression
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setError((err as any).response?.data?.message || (err as any).response?.data?.error || err.message || 'Failed to send OTP. Is the backend running?');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyOtp = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const validation = otpSchema.safeParse(otpCode);
    if (!validation.success) {
      setError(validation.error.issues[0].message);
      return;
    }

    setLoading(true);

    if (onAddApiLog) {
      onAddApiLog({ id: 'auth_verify', label: 'POST /api/v1/internal/auth/verify', method: 'POST' });
    }

    try {
      const serviceName = roleToServiceName(selectedRole!);
      const resp = await identityApi.auth.post('/api/v1/internal/auth/verify', undefined, { queries: { phoneNumber, otp: otpCode }, headers: { 'X-Calling-Service': serviceName } });

      // The backend returns { success: true, data: "<jwt_token>", message: "Login successful" }
      const token = resp?.data || resp;
      if (!token || typeof token !== 'string') {
        throw new Error('No token received from server');
      }

      // Store JWT
      setToken(token);

      // Decode user info from JWT
      const decoded = decodeJwt(token);
      const name = decoded?.name || decoded?.phoneNumber || phoneNumber;
      const id = decoded?.sub;

      // Store profile for session persistence
      setUserProfile({ id, phone: phoneNumber, role: selectedRole!, name });

      // Fetch profile to check if it is complete
      try {
        const profileResp = await identityApi.user.get('/api/v1/users/profile', { headers: { "X-User-Id": "" } });
        const p = profileResp?.data;
        if (!p?.name || !p?.email || p.name.trim() === '' || p.email.trim() === '') {
          setPendingLoginData({ id, phone: phoneNumber, role: selectedRole!, name });
          setShowProfileModal(true);
          return;
        } else {
          // If profile is already complete, just proceed
          setUserProfile({ id, phone: phoneNumber, role: selectedRole!, name: p.name });
          onLoginSuccess(selectedRole!, phoneNumber, p.name);
        }
      } catch (profileErr: unknown) {
        // If there's an error fetching profile, show the modal as a fallback
        setPendingLoginData({ id, phone: phoneNumber, role: selectedRole!, name });
        setShowProfileModal(true);
        return;
      }
    } catch (err: unknown) {
      // @ts-expect-error auto-migration type suppression
      if (err.status === 409 && err.data?.data?.activeSessions) {
        // @ts-expect-error auto-migration type suppression
        setActiveSessions(err.data.data.activeSessions);
        setShowSessionModal(true);
      } else {
        // @ts-expect-error auto-migration type suppression
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setError((err as any).response?.data?.message || (err as any).response?.data?.error || err.message || 'OTP verification failed');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    if (otpSent) {
      setOtpSent(false);
      setOtpCode('');
      setShowNotification(false);
    } else {
      setSelectedRole(null);
      setPhone('');
      setScrollY(0);
      if (scrollContainerRef.current) {
        scrollContainerRef.current.scrollTop = 0;
      }
    }
    setError('');
  };

  const autofillOtp = () => {
    setOtpCode(generatedOtp);
    setError('');
  };

  return (
    <div
      ref={scrollContainerRef}
      onScroll={handleScroll}
      className="w-full flex-1 flex flex-col justify-between bg-transparent pt-0 px-0 pb-4 sm:pt-0 sm:pb-6 relative overflow-y-auto overflow-x-hidden"
    >
      {/* Background ambient blurs */}
      <div className="absolute top-1/4 left-1/4 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-orange-400/10 rounded-full blur-3xl pointer-events-none z-0" />
      <div className="absolute bottom-1/4 right-1/4 translate-x-1/2 translate-y-1/2 w-64 h-64 bg-yellow-400/10 rounded-full blur-3xl pointer-events-none z-0" />

      {/* Sticky Shrinking Logo Header (only shown when selecting roles) */}
      {!selectedRole && (
        <div
          className={`sticky top-0 left-0 right-0 z-30 transition-all duration-300 flex flex-col items-center justify-center text-center pb-5 px-4 sm:px-6 rounded-b-3xl border-b backdrop-blur-xl ${theme === 'dark'
              ? 'bg-slate-900/20 border-rose-500/30/40 shadow-[0_10px_30px_rgba(0,0,0,0.2)]'
              : 'bg-white/20 border-white/30 shadow-[0_4px_20px_rgba(0,0,0,0.02)]'
            }`}
          style={{
            paddingTop: 'calc(1.25rem + env(safe-area-inset-top, 16px))'
          }}
        >
          {/* Theme Toggle inside Sticky Header */}
          <button
            onClick={toggleTheme}
            className={`absolute right-6 sm:right-8 top-1/2 -translate-y-1/2 p-2.5 rounded-xl border backdrop-blur-xl transition-all cursor-pointer z-40 ${theme === 'dark'
                ? 'bg-slate-900/20 border-rose-500/30/40 text-amber-400 hover:text-amber-300 shadow-[0_4px_20px_rgba(0,0,0,0.15)]'
                : 'bg-white/20 border-white/30 text-indigo-600 hover:text-indigo-800 shadow-sm'
              }`}
            style={{
              right: 'calc(1.5rem + env(safe-area-inset-right, 0px))'
            }}
            title="Toggle Light/Dark Mode"
          >
            {theme === 'dark' ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          </button>

          {/* Smoothly scaling logo wrapper */}
          <div
            className="transition-all duration-300 transform origin-center"
            style={{
              transform: `scale(${Math.max(0.72, Math.min(1.0, 1 - scrollY / 300))})`,
              opacity: Math.max(0.9, Math.min(1.0, 1 - scrollY / 550))
            }}
          >
            <LaBouffeLogo
              className="flex flex-col items-center gap-2.5 w-full"
              iconSize={scrollY > 10 ? "w-11 h-11" : "w-18 h-18"}
              align="center"
              textColorClass={theme === 'dark' ? 'text-white' : 'text-slate-800'}
            />
          </div>


        </div>
      )}

      {/* SMS Alert Notification Overlay */}
      <AnimatePresence>
        {showNotification && (
          <motion.div
            initial={{ opacity: 0, y: -80, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -80, scale: 0.95 }}
            className="absolute left-4 right-4 max-w-md mx-auto backdrop-blur-2xl bg-white/20 dark:bg-slate-900/20 border border-rose-500/20 dark:border-rose-500/30 text-slate-800 dark:text-[#f0ede6] p-4 rounded-2xl shadow-[0_15px_30px_rgba(249,115,22,0.1)] z-50 flex items-start gap-3 cursor-pointer hover:border-orange-500/50 transition-all hover:shadow-[0_0_12px_rgba(244,63,94,0.4)] dark:hover:shadow-[0_0_12px_rgba(244,63,94,0.5)] hover:border-rose-500/50 transition-all"
            style={{
              top: 'calc(1rem + env(safe-area-inset-top, 16px))'
            }}
            onClick={autofillOtp}
          >
            <div className="bg-orange-500 p-2 rounded-xl text-white shrink-0">
              <MessageSquare className="w-5 h-5" />
            </div>
            <div className="flex-1">
              <div className="flex justify-between items-center">
                <span className="font-bold text-xs text-orange-600 dark:text-orange-400 font-mono tracking-wider">SMS GATEWAY</span>
                <span className="text-[10px] text-slate-300 dark:text-slate-300">Just now</span>
              </div>
              <p className="text-sm font-semibold mt-1 text-slate-800 dark:text-[#f0ede6]">Your La Bouffe Login OTP is <span className="text-orange-600 dark:text-orange-400 font-mono text-base font-bold underline decoration-dotted">{generatedOtp}</span></p>
              <span className="text-[10px] text-slate-500 dark:text-[#f0ede6] mt-0.5 block">Tap this notification to autofill and proceed.</span>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Header */}
      {selectedRole && (
        <div
          className="shrink-0 flex items-center justify-between relative z-10 w-full max-w-7xl mx-auto px-4 sm:px-8"
          style={{
            marginTop: 'calc(0.375rem + env(safe-area-inset-top, 16px))'
          }}
        >
          <button
            onClick={handleBack}
            className={`p-2.5 rounded-xl transition-all border cursor-pointer backdrop-blur-md ${theme === 'dark' ? 'bg-slate-900 border-rose-500/30 text-slate-300 hover:bg-slate-800' : 'bg-white/20 border-rose-500/20 text-slate-600 dark:text-slate-300 hover:bg-white/20'
              }`}
          >
            <ArrowLeft className="w-5 h-5" />
          </button>
          <div className="flex items-center gap-1.5">
            <LaBouffeLogoMark className="w-6 h-6" />
            <span className={`font-bold text-sm ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>La Bouffe</span>
          </div>
          <button
            onClick={toggleTheme}
            className={`p-2.5 rounded-xl border transition-all cursor-pointer backdrop-blur-md ${theme === 'dark'
                ? 'bg-slate-900 border-rose-500/30 text-amber-400 hover:text-amber-300'
                : 'bg-white/20 border-rose-500/20 text-indigo-600 hover:bg-white/20'
              }`}
            title="Toggle Light/Dark Mode"
          >
            {theme === 'dark' ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
          </button>
        </div>
      )}

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col justify-start my-3 sm:my-6 relative z-10 w-full max-w-7xl mx-auto px-4 sm:px-8">
        <AnimatePresence mode="wait">
          {!selectedRole ? (
            <RoleSelector onSelectRole={setSelectedRole} />
          ) : (
            <AuthForm
              selectedRole={selectedRole}
              phone={phoneNumber}
              setPhone={setPhone}
              otpCode={otpCode}
              setOtpCode={setOtpCode}
              otpSent={otpSent}
              loading={loading}
              error={error}
              onSendOtp={handleSendOtp}
              onVerifyOtp={handleVerifyOtp}
              onResendOtp={async () => {
                setError('');
                setShowNotification(false);
                try {
                  const serviceName = roleToServiceName(selectedRole!);
                  await identityApi.auth.post('/api/v1/internal/auth/initiate', undefined, { queries: { phoneNumber }, headers: { 'X-Calling-Service': serviceName } });
                  if (import.meta.env.DEV || import.meta.env.VITE_ENABLE_DEV_OTP === 'true') {
                    try {
                      const adminResp = await identityApi.adminOtp.get('/api/v1/internal/auth/admin/otp', { queries: { phoneNumber, serviceName } });
                      if (adminResp?.data) {
                        setGeneratedOtp(adminResp.data);
                      } else if (typeof adminResp === 'string') {
                        setGeneratedOtp(adminResp);
                      }
                      setTimeout(() => setShowNotification(true), 1200);
                    } catch {
                      console.warn("Could not fetch OTP from admin endpoint.");
                    }
                  }
                } catch (err: unknown) {
                  // @ts-expect-error auto-migration type suppression
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any
                  setError((err as any).response?.data?.message || (err as any).response?.data?.error || err.message || 'Failed to resend OTP.');
                }
              }}
              onAutofillOtp={autofillOtp}
            />
          )}
        </AnimatePresence>
      </div>

      <SessionManagementModal
        isOpen={showSessionModal}
        onClose={() => setShowSessionModal(false)}
        sessions={activeSessions}
        phoneNumber={phoneNumber}
        otpCode={otpCode}
        serviceName={selectedRole ? roleToServiceName(selectedRole) : ''}
        theme={theme}
        onSuccess={async (token) => {
          setShowSessionModal(false);
          setToken(token);
          const decoded = decodeJwt(token);
          const name = decoded?.name || decoded?.phoneNumber || phoneNumber;
          const id = decoded?.sub;
          const role = selectedRole!;
          setUserProfile({ id, phone: phoneNumber, role, name });

          try {
            const profileResp = await identityApi.user.get('/api/v1/users/profile', { headers: { "X-User-Id": "" } });
            const p = profileResp?.data;
            if (!p?.name || !p?.email || p.name.trim() === '' || p.email.trim() === '') {
              setPendingLoginData({ id, phone: phoneNumber, role, name });
              setShowProfileModal(true);
            } else {
              setUserProfile({ id, phone: phoneNumber, role, name: p.name });
              onLoginSuccess(role, phoneNumber, p.name);
            }
          } catch (err: unknown) {
            setPendingLoginData({ id, phone: phoneNumber, role, name });
            setShowProfileModal(true);
          }
        }}
      />

      <CompleteProfileModal
        isOpen={showProfileModal}
        theme={theme}
        profileId={pendingLoginData?.id || ''}
        onComplete={(p) => {
          setShowProfileModal(false);
          const finalName = p.name || pendingLoginData?.name;
          if (pendingLoginData) {
            setUserProfile({ ...pendingLoginData, name: finalName });
            onLoginSuccess(pendingLoginData.role, pendingLoginData.phone, finalName);
          }
        }}
      />

      {/* Footer Disclaimer */}
      <div className="shrink-0 text-center space-y-1 sm:space-y-1.5 mt-auto relative z-10 w-full max-w-7xl mx-auto px-4 sm:px-8">
        <p className="text-[9.5px] sm:text-[10px] text-slate-300 dark:text-slate-300">
          By continuing, you agree to our terms & instant delivery guidelines.
        </p>
        <div className="flex items-center justify-center gap-3 text-[9px] sm:text-[10px] text-slate-300 dark:text-slate-300 font-mono">
          <span>SECURE END-TO-END</span>
          <span>•</span>
          <span>BIOMETRIC READY</span>
        </div>
        <div className="flex items-center justify-center gap-1.5 mt-1 sm:mt-2 text-[9px] font-mono tracking-wider text-orange-500 font-semibold bg-orange-500/10 px-2 py-0.5 rounded-full w-fit mx-auto border border-orange-500/15">
          <span className="w-1 h-1 rounded-full bg-orange-500 animate-pulse" />
          <span>TODAY'S SPECIAL: {foodNames[currentBgIndex].toUpperCase()}</span>
        </div>
      </div>
    </div>
  );
}

import { identityApi } from "@/lib/zodiosClients";
import { Button, Modal, Spinner } from '@shared/ui';
import { AlertTriangle, Monitor, Smartphone, Trash2 } from 'lucide-react';
import { useState } from 'react';

interface Session {
  sessionId: string;
  deviceInfo: string;
  os: string;
  browser: string;
  lastActive: number;
}

interface SessionManagementModalProps {
  isOpen: boolean;
  onClose: () => void;
  sessions: Session[];
  phoneNumber: string;
  otpCode: string;
  serviceName: string;
  onSuccess: (token: string) => void;
  theme?: 'light' | 'dark';
}

export default function SessionManagementModal({ isOpen, onClose, sessions, phoneNumber, otpCode, serviceName, onSuccess, theme = 'light' }: SessionManagementModalProps) {
  const [loadingId, setLoadingId] = useState<string | null>(null);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleRemoveDevice = async (sessionId: string) => {
    setLoadingId(sessionId);
    setError('');
    try {
      const resp = await identityApi.auth.post('/api/v1/internal/auth/verify', undefined, {
        queries: { phoneNumber, otp: otpCode, removeSessionId: sessionId },
        headers: { "X-Calling-Service": serviceName }
      });

      const token = resp?.data || resp;
      if (!token || typeof token !== 'string') {
        throw new Error('No token received from server');
      }
      onSuccess(token);
    } catch (err: unknown) {
      // @ts-expect-error auto-migration type suppression
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      setError((err as any).response?.data?.message || (err as any).response?.data?.error || err.message || 'Failed to remove device and login');
    } finally {
      setLoadingId(null);
    }
  };

  const getDeviceIcon = (os: string) => {
    const lower = os.toLowerCase();
    if (lower.includes('mac') || lower.includes('win') || lower.includes('linux')) return <Monitor className="w-5 h-5 text-indigo-500" />;
    return <Smartphone className="w-5 h-5 text-emerald-500" />;
  };

  const header = (
    <div className="flex items-center gap-3">
      <div className="p-3 bg-red-500/10 rounded-2xl">
        <AlertTriangle className="w-6 h-6 text-red-500" />
      </div>
      <div>
        <h3 className={`text-xl font-bold ${theme === 'dark' ? 'text-white' : 'text-slate-900'}`}>
          Session Limit Reached
        </h3>
        <p className={`text-sm mt-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
          You are already logged in on 2 devices. To continue, please log out of an existing device.
        </p>
      </div>
    </div>
  );

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      size="lg"
      header={header}
      className={theme === 'dark' ? 'bg-slate-900 border-rose-500/30' : 'bg-white border-slate-200'}
    >
      <div className="p-6 pt-2">
        {error && (
          <div className="mb-4 p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-500 text-sm">
            {error}
          </div>
        )}

        <div className="space-y-3">
          {sessions.map((session, idx) => (
            <div
              key={session.sessionId}
              className={`flex items-center justify-between p-4 rounded-2xl border transition-all ${theme === 'dark' ? 'bg-slate-800/20 border-slate-700 hover:border-slate-600' : 'bg-slate-50 border-slate-200 hover:border-slate-300'
                }`}
            >
              <div className="flex items-center gap-4">
                <div className={`p-2.5 rounded-xl ${theme === 'dark' ? 'bg-slate-700' : 'bg-white shadow-sm'}`}>
                  {getDeviceIcon(session.os)}
                </div>
                <div>
                  <p className={`font-bold text-sm ${theme === 'dark' ? 'text-white' : 'text-slate-800'}`}>
                    {session.os} &bull; {session.browser}
                  </p>
                  <p className={`text-xs mt-0.5 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
                    Last active: {new Date(session.lastActive).toLocaleString()}
                  </p>
                </div>
              </div>

              <Button
                onClick={() => handleRemoveDevice(session.sessionId)}
                disabled={loadingId !== null}
                variant="danger"
                className="!p-2 rounded-xl flex items-center justify-center cursor-pointer min-w-10 min-h-10"
                title="Log out from this device"
              >
                {loadingId === session.sessionId ? (
                  <Spinner size="md" className="text-white" />
                ) : (
                  <Trash2 className="w-5 h-5" />
                )}
              </Button>
            </div>
          ))}
        </div>

        <div className="mt-6 text-center">
          <p className={`text-xs ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>
            Logging out of a device will immediately invalidate its active session.
          </p>
        </div>
      </div>
    </Modal>
  );
}

import { useToast } from "@/contexts/ToastContext";
import { parseApiError } from '@/lib/parseApiError';
import { ledgerApi } from "@/lib/zodiosClients";
import { Badge, Button, Input, Select } from '@shared/ui';
import { ArrowRight, Check, ChevronLeft, ChevronRight, Copy, Filter, Search } from 'lucide-react';
import React, { useEffect, useState } from 'react';
import { asUntyped, WirePage } from '../../../lib/untypedResponse';

export default function AdminLedgerView() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [entries, setEntries] = useState<any[]>([]);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(1);
  const [loading, setLoading] = useState(false);
  const { showError } = useToast();

  // Filters
  const [transactionId, setTransactionId] = useState('');
  const [ownerId, setOwnerId] = useState('');
  const [ownerType, setOwnerType] = useState('');
  const [category, setCategory] = useState('');
  const [direction, setDirection] = useState('');

  const fetchEntries = async () => {
    setLoading(true);
    try {
      const queries: Record<string, unknown> = { page, size: 20 };
      if (transactionId) queries.transactionId = transactionId.trim();
      if (ownerId) queries.ownerId = ownerId.trim();
      if (ownerType) queries.ownerType = ownerType;
      if (category) queries.category = category;
      if (direction) queries.direction = direction;

      const res = await ledgerApi.ledger.get('/api/v1/ledger/admin/transactions', { queries: queries as unknown as Parameters<typeof ledgerApi.ledger.get>[1] extends { queries?: infer Q } ? Q : never });
      if (res) {
        const pageData = res.data || res;
        setEntries(asUntyped<WirePage<unknown>>(pageData).content ?? []);
        setTotalPages(asUntyped<WirePage<unknown>>(pageData).totalPages ?? 1);
      }
    } catch (e: unknown) {
      console.error(e);
      showError(parseApiError(e, 'Failed to fetch ledger transactions').message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEntries();
  }, [page]); // Re-fetch when page changes

  const handleFilter = (e: React.FormEvent) => {
    e.preventDefault();
    if (ownerId && !ownerType) {
      showError("Please select an Owner Type when searching by Owner ID");
      return;
    }
    if (ownerType && !ownerId) {
      showError("Please enter an Owner ID when filtering by Owner Type");
      return;
    }
    setPage(0);
    fetchEntries();
  };

  const clearFilters = () => {
    setTransactionId('');
    setOwnerId('');
    setOwnerType('');
    setCategory('');
    setDirection('');
    setPage(0);
    setTimeout(() => {
      fetchEntries();
    }, 0);
  };

  const [copiedTxnId, setCopiedTxnId] = useState<string | null>(null);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedTxnId(text);
    setTimeout(() => setCopiedTxnId(null), 2000);
  };

  // Directly use entries from the backend as they are now grouped transactions
  const groupedTransactions = entries;

  return (
    <div className="flex flex-col h-full bg-slate-50 dark:bg-[#0f111a] text-slate-800 dark:text-[#f0ede6] p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-black">Ledger Entries</h2>
      </div>

      {/* Filters */}
      <form onSubmit={handleFilter} className="glass-panel p-4 mb-6">
        <div className="flex items-center gap-2 mb-4">
            <Filter className="w-5 h-5 text-indigo-500" />
            <h3 className="font-bold">Filters</h3>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          <Input
            placeholder="Transaction ID"
            value={transactionId}
            onChange={(e) => setTransactionId(e.target.value)}
          />
          <Input
            placeholder="Owner ID"
            value={ownerId}
            onChange={(e) => setOwnerId(e.target.value)}
          />
          <Select
            value={ownerType}
            onChange={(val) => setOwnerType(val)}
            placeholder="All Owner Types"
            options={[
              { value: 'CUSTOMER', label: 'CUSTOMER' },
              { value: 'RESTAURANT', label: 'RESTAURANT' },
              { value: 'DRIVER', label: 'DRIVER' },
              { value: 'PLATFORM', label: 'PLATFORM' }
            ]}
          />
          <Select
            value={category}
            onChange={(val) => setCategory(val)}
            placeholder="All Categories"
            options={[
              { value: 'FOOD_COST', label: 'FOOD COST' },
              { value: 'DELIVERY_FEE', label: 'DELIVERY FEE' },
              { value: 'PLATFORM_FEE', label: 'PLATFORM FEE' },
              { value: 'TAX', label: 'TAX' },
              { value: 'REFUND', label: 'REFUND' },
              { value: 'DRIVER_EARNING', label: 'DRIVER EARNING' },
              { value: 'SETTLEMENT', label: 'SETTLEMENT' }
            ]}
          />
          <Select
            value={direction}
            onChange={(val) => setDirection(val)}
            placeholder="All Directions"
            options={[
              { value: 'CREDIT', label: 'CREDIT' },
              { value: 'DEBIT', label: 'DEBIT' }
            ]}
          />
        </div>
        <div className="mt-4 flex gap-3">
          <Button type="submit" className="flex-1" icon={<Search className="w-5 h-5" />}>
            Apply Filters
          </Button>
          <Button type="button" variant="secondary" onClick={clearFilters}>
            Clear
          </Button>
        </div>
      </form>

      {/* Table */}
      <div className="flex-1 glass-panel flex flex-col overflow-hidden">
        <div className="overflow-x-auto flex-1">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-100/50 dark:bg-slate-800/50 border-b border-slate-200 dark:border-slate-800">
                <th className="p-4 font-bold text-slate-500 uppercase text-xs tracking-wider">Date</th>
                <th className="p-4 font-bold text-slate-500 uppercase text-xs tracking-wider">Transaction Details</th>
                <th className="p-4 font-bold text-slate-500 uppercase text-xs tracking-wider">From Account</th>
                <th className="p-4 font-bold text-slate-500 uppercase text-xs tracking-wider">To Account</th>
                <th className="p-4 font-bold text-slate-500 uppercase text-xs tracking-wider text-right">Amount</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-slate-500 font-medium">
                    <div className="flex justify-center items-center gap-3">
                      <div className="w-5 h-5 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                      Loading transactions...
                    </div>
                  </td>
                </tr>
              ) : groupedTransactions.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-slate-500 font-medium bg-slate-50/50 dark:bg-slate-900/50">
                    No ledger transactions found.
                  </td>
                </tr>
              ) : (
                groupedTransactions.map(tx => (
                  <tr key={tx.transactionId} className="border-b border-slate-100 dark:border-slate-800/50 hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-all group">
                    <td className="p-4 align-middle">
                      <div className="flex flex-col">
