import { ZodiosError } from '@zodios/core';
import { isAxiosError } from 'axios';
import { z } from 'zod';
import { logger } from './logger';

// Schema for backend error response format (e.g., { message: "...", code: "..." })
const apiErrorSchema = z.object({
  message: z.string().optional(),
  code: z.string().optional(),
  error: z.string().optional(),
}).passthrough();

export interface ParsedApiError {
  message: string;
  statusCode?: number;
  originalError: unknown;
}

export function parseApiError(error: unknown, defaultMessage = 'An unexpected error occurred'): ParsedApiError {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const extractMessageFromData = (data: any): string | undefined => {
    if (!data) return undefined;
    if (typeof data === 'string') return data;

    // Array of errors (e.g., validation errors)
    if (Array.isArray(data.errors) && data.errors.length > 0) {
      if (typeof data.errors[0] === 'string') return data.errors[0];
      if (data.errors[0].message) return data.errors[0].message;
      if (data.errors[0].defaultMessage) return data.errors[0].defaultMessage;
    }

    // Spring Boot standard error / Custom ApiResponse
    if (data.message && typeof data.message === 'string') {
      // Check if this is an ApiResponse with a data object containing field errors
      if (data.data && typeof data.data === 'object' && !Array.isArray(data.data) && Object.keys(data.data).length > 0) {
        try {
          const detailedErrors = Object.entries(data.data)
            .map(([field, err]) => `${field}: ${err}`)
            .join(', ');
          return `${data.message}: ${detailedErrors}`;
        } catch (e: unknown) {
          // fallback to just the message
        }
      }
      return data.message;
    }

    if (data.error && typeof data.error === 'string') return data.error;
    if (data.details && typeof data.details === 'string') return data.details;
    if (data.reason && typeof data.reason === 'string') return data.reason;

    return undefined;
  };

  // If it's an Axios error (which Zodios uses under the hood for API errors)
  if (isAxiosError(error)) {
    logger.error('API Error (Axios)', error);

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const extractedMessage = extractMessageFromData((error as any).response?.data);

    if (extractedMessage) {
      return {
        message: extractedMessage,
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        statusCode: (error as any).response?.status,
        originalError: error,
      };
    }

    return {
      message: error.message || defaultMessage,
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      statusCode: (error as any).response?.status,
      originalError: error,
    };
  }

  // If it's a Zodios validation error
  if (error instanceof ZodiosError) {
    logger.error('API Validation Error (Zodios)', error);

    const extractedMessage = extractMessageFromData(error.data);

    if (extractedMessage) {
      return {
        message: extractedMessage,
        originalError: error,
      };
    }

    // Sometimes Zodios exposes the underlying axios error in .cause
    // @ts-expect-error auto-migration type suppression
    if (error.causee && isAxiosError(error.causee)) {
      // @ts-expect-error auto-migration type suppression
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const causeMsg = extractMessageFromData(error.cause(e as any).response?.data);
      if (causeMsg) {
        return {
          message: causeMsg,
          originalError: error,
        };
      }
    }

    return {
      message: error.message || defaultMessage,
      originalError: error,
    };
  }

  // Standard Error
  if (error instanceof Error) {
    logger.error('Application Error', error);
    return {
      message: error.message || defaultMessage,
      originalError: error,
    };
  }

  // Raw API response fallback if it's somehow an object
  if (typeof error === 'object' && error !== null) {
    const extractedMessage = extractMessageFromData(error);
    if (extractedMessage) {
      return {
        message: extractedMessage,
        originalError: error,
      };
    }
  }

  // String fallback
  if (typeof error === 'string') {
    return {
      message: error,
      originalError: error,
    };
  }

  logger.error('Unknown Error Type', error);
  return {
    message: defaultMessage,
    originalError: error,
  };
}

import { RoleName } from '../types';
/**
 * tokenStore.ts — Pure localStorage operations for auth state.
 * Has ZERO dependencies on apiClient to avoid circular imports.
 * apiClient.ts imports from here. authStore.ts imports from here + apiClient.
 */

// --- Token ---

export const setToken = (token: string) => {
  localStorage.setItem('auth_token', token);
};

export const getToken = (): string | null => {
  return localStorage.getItem('auth_token');
};

export const clearToken = () => {
  localStorage.removeItem('auth_token');
};

// --- Profile ---

// eslint-disable-next-line @typescript-eslint/no-explicit-any
let memoryProfile: any = null;

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const setUserProfile = (profile: any) => {
  memoryProfile = profile;
  localStorage.setItem('user_profile', JSON.stringify(profile));
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const getUserProfile = (): any | null => {
  if (memoryProfile) return memoryProfile;

  const stored = localStorage.getItem('user_profile');
  if (stored) {
    try {
      memoryProfile = JSON.parse(stored);
      if (!memoryProfile.id) {
        const token = getToken();
        if (token) {
          const decoded = decodeJwt(token);
          if (decoded && decoded.sub) {
            memoryProfile.id = decoded.sub;
            setUserProfile(memoryProfile);
          }
        }
      }
      if (!memoryProfile.phone && memoryProfile.phoneNumber) {
        memoryProfile.phone = memoryProfile.phoneNumber;
      }

      return memoryProfile;
    } catch {
      // a corrupt/absent stored profile is expected; fall through to the null return
    }
  }

  // Fallback: decode from JWT
  const token = getToken();
  if (token) {
    const decoded = decodeJwt(token);
    if (decoded && decoded.sub) {
      const role = Array.isArray(decoded.roles) && decoded.roles.length > 0
        ? decoded.roles[0].toUpperCase()
        : (decoded.role || RoleName.CUSTOMER).toUpperCase();
      const profile = { id: decoded.sub, phone: decoded.phone || decoded.sub, role, name: decoded.name || '' };
      setUserProfile(profile);
      return profile;
    }
  }
  return null;
};

// --- JWT Decode ---

export const decodeJwt = (token: string) => {
  try {
    const base64Url = token.split('.')[1];
    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
    const jsonPayload = decodeURIComponent(window.atob(base64).split('').map(function(c) {
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
    return JSON.parse(jsonPayload);
  } catch (e: unknown) {
    return null;
  }
};

// --- Full Cleanup ---

export const clearAllLocalData = () => {
  clearToken();
  localStorage.removeItem('user_profile');
  localStorage.removeItem('device_id');
  localStorage.removeItem('deliveryAddressId');
  localStorage.removeItem('food_delivery_cart');
  localStorage.removeItem('food_delivery_cart_restaurant');
  const keysToRemove: string[] = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key && (key.startsWith('auth_') || key.startsWith('user_') || key.startsWith('device_') || key.startsWith('session_') || key.startsWith('food_delivery_cart') || key.startsWith('restaurant_') || key.startsWith('order_'))) {
      keysToRemove.push(key);
    }
  }
  keysToRemove.forEach(k => localStorage.removeItem(k));
  memoryProfile = null;
};

